(() => {
  const form = document.querySelector('#indonesia-visa-form');
  if (!form) return;
  const type = document.querySelector('#indonesia-visa-type'), speed = document.querySelector('#indonesia-speed'), quantity = document.querySelector('#indonesia-quantity'), price = document.querySelector('#indonesia-price'), total = document.querySelector('#indonesia-total'), note = document.querySelector('#indonesia-speed-note'), docs = document.querySelector('#indonesia-documents'), feedback = document.querySelector('#indonesia-feedback'), submit = form.querySelector('[type="submit"]');
  const indonesiaVisaLabels = {'id-b1':'Visa Elektronik Saat Kedatangan (B1) · sekali masuk, 30 hari','id-c1':'Wisatawan (C1) · sekali masuk, 60 hari','id-e31a-1':'Pasangan Warga Negara Indonesia (E31A) · 1 tahun','id-e31a-2':'Pasangan Warga Negara Indonesia (E31A) · 2 tahun','id-e31b-1':'Pasangan Pemegang ITAS (E31B) · 1 tahun','id-e31b-2':'Pasangan Pemegang ITAS (E31B) · 2 tahun','id-e31c-1':'Anak Warga Negara Indonesia (E31C) · 1 tahun','id-e31c-2':'Anak Warga Negara Indonesia (E31C) · 2 tahun','id-e31d-1':'Anak tiri Warga Negara Indonesia (E31D) · 1 tahun','id-e31d-2':'Anak tiri Warga Negara Indonesia (E31D) · 2 tahun','id-e31e-1':'Anak Pemegang ITAS (E31E) · 1 tahun','id-e31e-2':'Anak Pemegang ITAS (E31E) · 2 tahun','id-e31f-1':'Anak adopsi Warga Negara Indonesia (E31F) · 1 tahun','id-e31f-2':'Anak adopsi Warga Negara Indonesia (E31F) · 2 tahun','id-e31g-1':'Orang tua Warga Negara Indonesia (E31G) · 1 tahun','id-e31g-2':'Orang tua Warga Negara Indonesia (E31G) · 2 tahun','id-e31h-1':'Orang tua Pemegang ITAS (E31H) · 1 tahun','id-e31h-2':'Orang tua Pemegang ITAS (E31H) · 2 tahun','id-e33g-1':'Nomaden Digital (E33G) · 1 tahun'};
  const originalVisaLabels = new Map([...type.options].map(option => [option.value, option.textContent]));
  const syncIndonesiaLanguage = () => [...type.options].forEach(option => { if (option.value) option.textContent = document.documentElement.lang === 'id' ? indonesiaVisaLabels[option.value] : originalVisaLabels.get(option.value); });
  syncIndonesiaLanguage();
  document.querySelector('#language')?.addEventListener('change', () => setTimeout(syncIndonesiaLanguage));
  const b1 = { normal: [750000, '3–5 hari kerja'], express: [1000000, '2 hari kerja'], 'super-express': [1250000, '1 hari kerja'] };
  const c1 = { normal: [1800000, '14 hari kerja'], express: [2800000, '10 hari kerja'], 'super-express': [3800000, '7 hari kerja'] };
  const familyOne = { normal: [13500000, '14 hari kerja'], express: [15000000, '10 hari kerja'], 'super-express': [17000000, '7 hari kerja'] };
  const familyTwo = { normal: [16500000, '14 hari kerja'], express: [18000000, '10 hari kerja'], 'super-express': [20000000, '7 hari kerja'] };
  const nomad = { normal: [12500000, '14 hari kerja'], express: [15000000, '10 hari kerja'], 'super-express': [17000000, '7 hari kerja'] };
  const visas = { 'id-b1': b1, 'id-c1': c1, 'id-e31a-1': familyOne, 'id-e31a-2': familyTwo, 'id-e31b-1': familyOne, 'id-e31b-2': familyTwo, 'id-e31c-1': familyOne, 'id-e31c-2': familyTwo, 'id-e31d-1': familyOne, 'id-e31d-2': familyTwo, 'id-e31e-1': familyOne, 'id-e31e-2': familyTwo, 'id-e31f-1': familyOne, 'id-e31f-2': familyTwo, 'id-e31g-1': familyOne, 'id-e31g-2': familyTwo, 'id-e31h-1': familyOne, 'id-e31h-2': familyTwo, 'id-e33g-1': nomad };
  const standardDocuments = [['face', 'Foto diri (tanpa kacamata)', true, '.jpg,.jpeg,.png', 'visa-face.png', 'visa-face-sample.jpg'], ['passport', 'Halaman biodata paspor', true, '.pdf,.jpg,.jpeg,.png', 'visa-passport.png', 'visa-passport-sample.jpg'], ['ticket', 'Tiket penerbangan', false, '.pdf,.jpg,.jpeg,.png', 'visa-ticket.png'], ['hotel', 'Bukti reservasi hotel', false, '.pdf,.jpg,.jpeg,.png', 'visa-hotel.png'], ['additional-one', 'Dokumen tambahan 1', false, '.pdf,.jpg,.jpeg,.png', 'visa-document.png'], ['additional-two', 'Dokumen tambahan 2', false, '.pdf,.jpg,.jpeg,.png', 'visa-document.png']];
  const documentsForType = () => {
    if (type.value === 'id-b1') return standardDocuments.map(card => ['ticket', 'hotel'].includes(card[0]) ? [...card.slice(0, 2), true, ...card.slice(3)] : card);
    if (type.value === 'id-c1') return [standardDocuments[0], standardDocuments[1], ['bank-statement', 'Bank statement minimum USD $2.000 atau setara', true, '.pdf,.jpg,.jpeg,.png', 'visa-document.png'], ...standardDocuments.slice(2, 5)];
    if (/^id-e31a-/.test(type.value)) return [standardDocuments[0], standardDocuments[1], ['ticket', 'Tiket penerbangan', true, '.pdf,.jpg,.jpeg,.png', 'visa-ticket.png'], standardDocuments[3], ['bank-statement', 'Bank statement minimum USD $2.000 atau setara', true, '.pdf,.jpg,.jpeg,.png', 'visa-document.png'], ['curriculum-vitae', 'Daftar riwayat hidup (Curriculum Vitae)', true, '.pdf,.jpg,.jpeg,.png', 'visa-document.png'], ['spouse-application', 'Permohonan dari suami atau istri (Warga Negara Indonesia)', true, '.pdf,.jpg,.jpeg,.png', 'visa-document.png'], ['marriage-record', 'Bukti pencatatan pernikahan', true, '.pdf,.jpg,.jpeg,.png', 'visa-document.png']];
    return standardDocuments;
  };
  const money = value => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
  const applicants = () => Math.min(10, Math.max(1, Number(quantity.value) || 1));
  const renderDocs = () => { const documentCards = documentsForType(); docs.innerHTML = Array.from({ length: applicants() }, (_, index) => `<details class="visa-applicant" ${index === 0 ? 'open' : ''}><summary><b>Pemohon ${index + 1} — Dokumen</b><span>0 file dipilih</span></summary><div class="visa-upload-grid">${documentCards.map(([key, label, required, accept, icon, preview]) => `<label class="visa-document-card${preview ? ' has-preview' : ''}"><img class="visa-document-icon" src="/assets/${icon}" alt="" aria-hidden="true">${preview ? `<span class="visa-document-preview"><img src="/assets/${preview}" alt="Contoh ${label}"></span>` : ''}<b>${label}${required ? ' *' : ''}</b><small>Klik untuk upload</small><input name="${key}_${index + 1}${key.startsWith('additional') ? '[]' : ''}" type="file" ${required ? 'required' : ''} ${key.startsWith('additional') ? 'multiple' : ''} accept="${accept}"></label>`).join('')}</div></details>`).join(''); docs.querySelectorAll('.visa-applicant').forEach(item => { item.addEventListener('change', () => { const selected = [...item.querySelectorAll('input[type=file]')].reduce((sum, input) => sum + (input.files?.length || 0), 0); item.querySelector('summary span').textContent = `${selected} file dipilih`; }); item.addEventListener('toggle', () => { if (item.open) docs.querySelectorAll('.visa-applicant[open]').forEach(other => { if (other !== item) other.open = false; }); }); }); };
  const refresh = () => { const selection = visas[type.value]?.[speed.value], ready = Boolean(selection); price.textContent = money(selection?.[0] || 0); total.textContent = money((selection?.[0] || 0) * applicants()); note.textContent = selection ? `${speed.options[speed.selectedIndex].text} · ${selection[1]}` : 'Pilih kecepatan proses'; docs.hidden = !ready; submit.disabled = !ready; if (ready) renderDocs(); };
  [type, speed, quantity].forEach(control => control.addEventListener('input', refresh));
  window.addVisaAddressFields(form);
  form.querySelector('[name="phone"]').addEventListener('input', event => { event.target.value = event.target.value.replace(/\D/g, ''); });
  refresh();
  form.addEventListener('submit', async event => { event.preventDefault(); const data = new FormData(form); data.append('country', 'ID'); data.append('visaType', type.value); data.append('processingSpeed', speed.value); data.append('quantity', quantity.value); feedback.textContent = 'Mengirim aplikasi…'; try { const response = await fetch('/api/visa/create.php', { method: 'POST', body: data }); const result = await response.json(); if (!response.ok || !result.ok) throw new Error(result.message || 'Tidak dapat mengirim aplikasi.'); feedback.textContent = 'Aplikasi diterima.'; if (result.paymentUrl) location.href = result.paymentUrl; } catch (error) { feedback.textContent = error.message || 'Koneksi pembayaran belum tersedia. Silakan hubungi tim kami.'; } });
})();
